const cache = new Map();
export function getBakedSprite(key) {
  let s = cache.get(key);
  if (s) return s;
  const rec = RAW_SPRITES[key];
  if (!rec) return null;
  const [w, h, b64] = rec;
  const bin = atob(b64);
  const d = new Uint8Array(w * h);
  for (let i = 0; i < d.length; i++) d[i] = bin.charCodeAt(i);
  s = { w, h, d };
  cache.set(key, s);
  return s;
}
